-- creature_template: `scale` was removed (2026_03_22_03); use creature_template_model.DisplayScale.
-- `mechanic_immune_mask` / `spell_school_immune_mask` removed (2026_03_22_03); use `CreatureImmunitiesId` -> `creature_immunities` (MechanicsMask = old mechanic mask * 2).
-- trainer_type / trainer_spell / trainer_class / trainer_race were also dropped upstream.
DELETE FROM `creature_template` WHERE `entry` IN (99003, 99004, 99005, 99006, 99007, 99008, 99009, 99010, 99011, 99012, 99013);
DELETE FROM `creature_template_model` WHERE `CreatureID` IN (99003, 99004, 99005, 99006, 99007, 99008, 99009, 99010, 99011, 99012, 99013);
DELETE FROM `creature_immunities` WHERE `ID` IN (99099001, 99099002);



